import{_ as e,o as a,c as d,ag as o}from"./chunks/framework.By9v0nLp.js";const p=JSON.parse('{"title":"Commands","description":"","frontmatter":{},"headers":[],"relativePath":"using/commands.md","filePath":"using/commands.md"}'),s={name:"using/commands.md"};function r(l,t,i,n,c,g){return a(),d("div",null,[...t[0]||(t[0]=[o(`<h1 id="commands" tabindex="-1">Commands <a class="header-anchor" href="#commands" aria-label="Permalink to &quot;Commands&quot;">​</a></h1><p>Every command starts with <code>/dialog</code> and needs permission level 2 (operators, command blocks, functions, and quest or NPC mods running with raised permissions). Dialog ids tab-complete.</p><h2 id="conversations" tabindex="-1">Conversations <a class="header-anchor" href="#conversations" aria-label="Permalink to &quot;Conversations&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>What it does</th></tr></thead><tbody><tr><td><code>/dialog start &lt;players&gt; &lt;dialog&gt; [node]</code></td><td>Starts a conversation, at <code>node</code> if given</td></tr><tr><td><code>/dialog stop &lt;players&gt;</code></td><td>Closes the conversation without finishing it</td></tr><tr><td><code>/dialog bind &lt;entities&gt; &lt;dialog&gt; [node]</code></td><td>Right-clicking these entities starts the dialog. See <a href="/wiki/nostalgicdialog/using/starting#talk-to-a-mob-or-npc">Starting Dialogs</a></td></tr><tr><td><code>/dialog unbind &lt;entities&gt;</code></td><td>Removes the binding</td></tr><tr><td><code>/dialog list</code></td><td>Lists every loaded dialog and how many speakers are loaded</td></tr></tbody></table><h2 id="player-data" tabindex="-1">Player data <a class="header-anchor" href="#player-data" aria-label="Permalink to &quot;Player data&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>What it does</th></tr></thead><tbody><tr><td><code>/dialog flag set &lt;players&gt; &lt;flag&gt;</code></td><td>Sets a flag</td></tr><tr><td><code>/dialog flag clear &lt;players&gt; &lt;flag&gt;</code></td><td>Clears a flag</td></tr><tr><td><code>/dialog flag has &lt;player&gt; &lt;flag&gt;</code></td><td>Shows <code>true</code> or <code>false</code>, and returns 1 or 0</td></tr><tr><td><code>/dialog relationship add &lt;players&gt; &lt;npc&gt; &lt;points&gt;</code></td><td>Adds points (negative to take away)</td></tr><tr><td><code>/dialog relationship set &lt;players&gt; &lt;npc&gt; &lt;points&gt;</code></td><td>Sets points</td></tr><tr><td><code>/dialog relationship get &lt;player&gt; &lt;npc&gt;</code></td><td>Shows the points, and returns them</td></tr><tr><td><code>/dialog reset &lt;players&gt;</code></td><td>Clears all flags, relationships and seen dialogs</td></tr><tr><td><code>/dialog reset &lt;players&gt; flags</code></td><td>Clears flags only (also <code>relationships</code> or <code>seen</code>)</td></tr><tr><td><code>/dialog info &lt;player&gt;</code></td><td>Shows a player&#39;s flags, relationships and how many dialogs they&#39;ve finished</td></tr></tbody></table><h2 id="using-results-in-command-blocks" tabindex="-1">Using results in command blocks <a class="header-anchor" href="#using-results-in-command-blocks" aria-label="Permalink to &quot;Using results in command blocks&quot;">​</a></h2><p><code>flag has</code> and <code>relationship get</code> return a number, so other commands can use them with <code>execute store</code>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>execute store result score @p elder_trust run dialog relationship get @p elder</span></span>
<span class="line"><span>execute if score @p elder_trust matches 10.. run say The elder trusts you!</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>execute store result score @p met run dialog flag has @p met_elder</span></span></code></pre></div><h2 id="common-recipes" tabindex="-1">Common recipes <a class="header-anchor" href="#common-recipes" aria-label="Permalink to &quot;Common recipes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Goal</th><th>Command</th></tr></thead><tbody><tr><td>Test a dialog from the start</td><td><code>/dialog reset @s</code> then <code>/dialog start @s mypack:elder</code></td></tr><tr><td>Jump to a node while writing</td><td><code>/dialog start @s mypack:elder menu</code></td></tr><tr><td>Pretend a quest step is done</td><td><code>/dialog flag set @s quest_wood_done</code></td></tr><tr><td>See what a player has done</td><td><code>/dialog info Steve</code></td></tr><tr><td>Reload after editing files</td><td><code>/reload</code></td></tr></tbody></table>`,12)])])}const m=e(s,[["render",r]]);export{p as __pageData,m as default};
